#include <iostream>
#include <iomanip>

int main() {
    // Part 1: Exercise 5 Demo (Decimal-aligned column display)
    std::cout << std::fixed << std::setprecision(3);
    double col1[4] = {0.63, 12.78, -124.6, 65.7};
    double col2[4] = {64.1, -11.678, 59.002, -1200.654};

    std::cout << "BANG SO THUC (CAN PHAI / CAN DAU THAP PHAN):\n";
    for (int i = 0; i < 4; ++i) {
        std::cout << std::setw(10) << col1[i] << " " 
                  << std::setw(12) << col2[i] << "\n";
    }

    // Part 2: Exercise 7 Complete Solution
    int nam = 0;
    char a = ' ', b = ' ', c = ' ', d = ' ', e = ' ';

    if (std::cin >> nam) {
        std::cin.ignore(1000, '\n'); // Clear newline left in buffer
        std::cin.get(a);
        std::cin.get(b);
        std::cin.get(c);
        std::cin.get(d);
        std::cin.get(e);
        std::cout << a << b << c << d << e << " nam " << nam << "\n";
    }
    return 0;
}
